-- Seed FAQ for service, main, buyout pages
INSERT INTO faqs (page_slug, question, answer, sort_order, is_published, include_in_schema)
VALUES
  -- Сервис (5 вопросов)
  ('service', 'Как записаться на сервисное обслуживание?', 'Записаться на ТО можно на странице Сервис — выберите ближайший сервисный центр, дату и удобное время. Мастер подтвердит запись по телефону.', 0, true, true),
  ('service', 'Сколько стоит ТО для автомобилей ваших брендов?', 'Стоимость ТО зависит от модели и пробега. Во время записи мастер рассчитает точную стоимость. Регулярное ТО — от 6 тыс. рублей.', 1, true, true),
  ('service', 'Есть ли гарантия на выполненные работы?', 'Да, мы даём гарантию на все виды работ. Гарантийные документы оформляются автоматически в системе. Срок гарантии — до 2 лет.', 2, true, true),
  ('service', 'Можно ли приобрести запчасти без ремонта?', 'Конечно! Все оригинальные запчасти для автомобилей SKODA, Volkswagen, Mercedes-Benz, Exeed в наличии на складе. Заказ оформляется за 1–2 дня.', 3, true, false),
  ('service', 'Работаете ли вы по программе техобслуживания?', 'Да, мы проводим все виды технического обслуживания по гарантийной программе производителя: ТО-0, ТА-0, ТО-1 и т.д.', 4, true, true),

  -- Главная (4 вопроса)
  ('main', 'Какие бренды вы представляете в Брянске?', 'Мы — официальный дилер SKODA, Volkswagen, Mercedes-Benz, EXEED, Chery, Haval, Jetour в Брянске. Каталог новых и подержанных авто — на сайте.', 0, true, true),
  ('main', 'Можно ли купить авто в кредит?', 'Да, у нас действует программа кредитования: ставка от 0%, первоначальный взнос от 0%, срок до 7 лет. Одобрение за 15 минут.', 1, true, true),
  ('main', 'Принимаете ли старый автомобиль по trade-in?', 'Бесспорно! Привезите своё авто на оценку — мы произведём бесплатную диагностику, оформим все документы и зачитаем цену в стоимость нового.', 2, true, true),
  ('main', 'Где находятся ваши салоны?', 'Адреса всех автосалонов указаны на странице «Контакты» и в карточке каждого бренда. Работаем ежедневно с 9:00 до 21:00.', 3, true, false),

  -- Выкуп (4 вопроса)
  ('buyout', 'Как узнать предварительную стоимость моего авто?', 'Заполните краткую форму на странице «Выкуп»: марка, модель, год, пробег. Система оценит рыночную стоимость за 1 минуту.', 0, true, true),
  ('buyout', 'Нужно ли приезжать в салон для оценки?', 'Необязательно — можно получить предварительную оценку онлайн. Для финального выкупа специалист проведёт осмотр на месте.', 1, true, true),
  ('buyout', 'Выкупаете ли машины с пробегом и с проблемами?', 'Выкупаем автомобили в любом состоянии: с пробегом, после ДТП, с неисправными двигателем или кУЗов. Конечная цена зависит от состояния.', 2, true, true),
  ('buyout', 'Как быстро я получу деньги?', 'После оформления всех документов выкуп занимает 1–2 дня. Деньги переводятся на карту или выдаются наличными — по вашему выбору.', 3, true, true)
-- Предупреждение: перед запуском проверите, что данные ещё не сидированы
